import{_ as e,o as i,c as o,a0 as a}from"./chunks/framework.BL79I5mR.js";const p=JSON.parse('{"title":"Explicit 1D finite volume routing (FLOW_ROUTING FV)","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/engine-modifications/06-finite-volume-routing.md","filePath":"explanation/engine-modifications/06-finite-volume-routing.md"}'),d={name:"explanation/engine-modifications/06-finite-volume-routing.md"};function n(r,t,l,s,c,h){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="explicit-1d-finite-volume-routing-flow-routing-fv" tabindex="-1">Explicit 1D finite volume routing (<code>FLOW_ROUTING FV</code>) <a class="header-anchor" href="#explicit-1d-finite-volume-routing-flow-routing-fv" aria-label="Permalink to &quot;Explicit 1D finite volume routing (`FLOW_ROUTING FV`)&quot;">​</a></h1><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Official SWMM only offers implicit schemes with linearization (dynamic wave) or kinematic/steady waves. The dynamic wave solver, although it is the industry standard, has well-documented difficulties with transcritical flow, the propagation of sharp fronts and the dry/wet transition. The <code>FLOW_ROUTING FV</code> extension adds an <em>explicit and conservative</em> 1D finite volume solver of Godunov type, which natively solves transcritical flow and handles dry/wet without the ad hoc branches of the dynamic wave.</p><h2 id="solver-architecture" tabindex="-1">Solver architecture <a class="header-anchor" href="#solver-architecture" aria-label="Permalink to &quot;Solver architecture&quot;">​</a></h2><p>The solver lives in <code>src/engine/hydraulics/fv/</code>. Each conduit is discretized into cells (by default at least <code>FV_MIN_CELLS</code> = 4 per conduit, or with a target length <code>FV_CELL_LENGTH</code>); the conserved state of each cell is the hydraulic area $A$ and the flow $Q$. The global time step obeys the Courant condition, and the solver sub-steps internally to its own CFL limit, so the routing step (reporting/forcing) does not need to shrink for stability.</p><p>The main options (keys <code>FV_*</code> in <code>[OPTIONS]</code>) are:</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>FV_CFL</code></td><td>0.5</td><td>Courant number</td></tr><tr><td><code>FV_RIEMANN</code></td><td>HLLC</td><td>Riemann solver (HLL / HLLC)</td></tr><tr><td><code>FV_ORDER</code></td><td>1</td><td>spatial order (1 = Godunov, 2 = MUSCL–Hancock)</td></tr><tr><td><code>FV_LIMITER</code></td><td>MINMOD</td><td>slope limiter (MINMOD/VANLEER/SUPERBEE)</td></tr><tr><td><code>FV_CELL_LENGTH</code></td><td>0</td><td>target $\\Delta x$ (0 = cells floor only)</td></tr><tr><td><code>FV_MIN_CELLS</code></td><td>4</td><td>cells floor per conduit</td></tr><tr><td><code>FV_SLOT_CELERITY</code></td><td>100 ft/s</td><td>pressure celerity (slot width)</td></tr><tr><td><code>FV_NODE_COUPLING</code></td><td>SEMI_IMPLICIT</td><td>node–cell coupling</td></tr><tr><td><code>FV_STRUCTURE_COUPLING</code></td><td>SUBSTEP</td><td>when structures are re-evaluated</td></tr><tr><td><code>FV_LTS</code></td><td>true</td><td>local time stepping</td></tr><tr><td><code>FV_LTS_MAX_TIERS</code></td><td>6</td><td>maximum LTS levels</td></tr><tr><td><code>FV_DISPERSION</code></td><td>0</td><td>longitudinal dispersion coefficient</td></tr></tbody></table><p><em>Table: Options of the 1D finite volume solver.</em></p><h2 id="key-designs" tabindex="-1">Key designs <a class="header-anchor" href="#key-designs" aria-label="Permalink to &quot;Key designs&quot;">​</a></h2><ul><li><strong>Algebraic nodes</strong>: junction chambers are not states with area (as in the dynamic wave, where the working area belongs to the conduits); a degree-2 node without lateral inflow passes flows directly as a face, and the remaining nodes solve their head from the instantaneous flow balance per substep. This eliminates the millisecond step limit that a chamber area imposed on the whole model.</li><li><strong>Semi-implicit node–cell coupling</strong>: the flow of each coupling face is linearized in the node head, which takes the node out of the explicit stability limit (the chamber, not the pipe, was the limiting factor of the substep). Conservation is not altered: the corrected flow is what both the node and the cell see. With <code>FV_NODE_PICARD_SWEEPS</code> &gt; 1, area, width and Riemann flows are re-evaluated in each sweep.</li><li><strong>Local time stepping (LTS)</strong>: stiff cells (short, pressurized conduits) advance at their own $\\Delta t = 2^k,\\Delta t_0$ while the rest advance at the global step; when the split separates nothing, the solver falls back to the bit-for-bit global step path.</li><li><strong>Structures</strong>: pump/orifice/weir/outfall equations are re-evaluated by default in <em>every</em> explicit substep (<code>FV_STRUCTURE_COUPLING SUBSTEP</code>), which is physically exact; the alternative is once per routing step.</li><li><strong>Backends</strong>: the same scalar kernel is compiled for CPU, OpenMP and devices (CUDA/HIP/SYCL via Kokkos plugins); the result must be bit for bit identical across backends.</li></ul>',10)])])}const f=e(d,[["render",n]]);export{p as __pageData,f as default};
